COMMENT ON COLUMN kb_document.indexed_at IS '最近一次索引完成时间';
COMMENT ON COLUMN kb_document.is_deleted IS '是否逻辑删除';

COMMENT ON COLUMN kb_doc_chunk.id IS '文档分块主键';
