INSERT INTO public.kb_doc_chunk (id, doc_id, kb_id, chunk_index, content, embedding, page_num, section_title, token_count, doc_version, created_at) VALUES (185, 7, 2, 0, '技术规范文档 v1.4
技术委员会 2025 年修订版

第一章 代码规范

1.1 提交规范

所有代码提交必须遵循以下 Commit Message 格式：

type(scope): message

type 类型：
- feat：新功能。
- fix：Bug 修复。
- docs：文档修改。
- refactor：重构，不影响功能。
- perf：性能优化。
- test：测试相关。
- chore：构建工具、依赖等变更。

示例：

feat(payment): 新增微信支付接口
fix(order): 修复订单金额计算精度问题

1.2 分支策略

主要分支：
- main：生产环境代码，只接受来自 release 分支的 PR。
- develop：开发主分支，日常开发在此基础上创建特性分支。
- feature/xxx：特性开发分支，从 develop 创建，完成后 PR 到 develop。
- hotfix/xxx：紧急修复分支，从 main 创建，完成后同时 PR 到 main 和 develop。', '[-0.09445123,-0.012107637,-0.01859873,0.015061666,-0.008643453,-0.051695526,0.027363647,0.04924679,-0.028801793,-0.0024754577,-0.012991902,0.041239817,0.046953533,0.036575556,-0.030822972,-0.020270089,0.026566837,-0.030492587,0.025886633,-0.036031395,-0.016480379,0.0046496824,0.034010217,0.03855787,0.034146257,0.03673103,-0.019852249,-0.06934197,0.09173041,-0.030648062,0.029073875,-0.013749844,-0.009590881,-0.05740924,-0.04372742,-0.041589633,0.017714463,-0.029481998,-0.07594967,-0.011233089,-0.018754205,-0.02301034,-0.024759436,-0.036148,0.050101906,-0.025906067,-0.015683567,-0.04730335,0.0140413605,-0.0022616794,-0.019900834,-0.017471533,0.055310328,-0.052744985,0.04407724,0.054338608,-0.01862788,-0.026741747,-0.053833313,-0.019842532,-0.062306713,0.033621527,0.025206428,0.020328391,-0.0033597234,0.014089947,0.0065542543,-0.015236576,0.019162327,-0.03803314,0.004156534,0.033971347,-0.0025070386,-0.041434158,-0.07361754,0.018501557,0.05946929,-0.031406004,-0.025944935,0.008580292,0.023709979,0.019939704,0.021844275,-0.024215274,0.016451227,-0.047769777,0.018948548,0.03861617,-0.0063453345,-0.0061412733,-0.039782234,-0.064949796,0.0024487355,-0.046836924,-0.013458328,0.003298991,-0.04431045,0.04271683,0.026469665,0.03177526,-0.019444127,0.0014308583,0.04170624,-0.081779994,0.053366885,0.0029977576,0.09134172,-0.0026892363,-0.04602068,-0.010484863,0.0041832565,0.015984802,0.010173913,-0.005864333,-0.0026770898,-0.040073752,0.029209916,-0.040695652,0.04364968,0.016946804,-0.02252448,-0.03027881,0.029248785,-0.008526847,0.007982683,-0.07260695,0.0040253517,0.07408397,-0.011563473,0.008808645,0.01730634,0.035992526,-0.006962377,-0.008347078,-0.0590806,-0.0216888,-0.012253394,-0.02314638,0.0073121963,-0.05787567,0.035390057,-0.0012911735,-0.07657157,-0.025420206,0.024429051,-0.07136315,0.034748722,-0.0021572195,0.020036876,-0.0010063379,0.033757567,0.0035516382,0.051384576,-0.0036682447,0.061334994,-0.044232715,