INSERT INTO public.kb_doc_chunk (id, doc_id, kb_id, chunk_index, content, embedding, page_num, section_title, token_count, doc_version, created_at) VALUES (216, 13, 1, 5, '• 每年一次全面健康体检（含部分专项检查）

• 弹性餐饮补贴：每工作日50元餐补（随工资发放）

• 交通补贴：市区内岗位600元/月，郊区岗位1,000元/月

• 生日礼金：500元购物卡

• 节日福利：春节、中秋、端午节均发放实物礼包

• 员工学习基金：每人每年3,000元，可用于购买课程、书籍或参加行业会议

