INSERT INTO public.kb_doc_chunk (id, doc_id, kb_id, chunk_index, content, embedding, page_num, section_title, token_count, doc_version, created_at) VALUES (224, 13, 1, 13, '公司设立专业技术（P序列）与管理（M序列）双通道晋升体系。员工可根据自身发展方向选择晋升路径，不强制由技术转管理。

• 晋升评审每年10月启动，由用人部门提名，HR组织评审委员会评定

• 晋升须满足：在当前级别至少满12个月，且最近两次绩效不低于B

• 员工可向HR申请职业发展面谈，每年至少进行一次

第九章 离职管理

9.1 主动离职流程

员工主动离职须提前书面通知：试用期员工提前3天，正式员工（P6以下）提前30天，P7及以上员工提前60天，管理层（M3及以上）提前90天。

9.2 离职交接清单

• 工作文档及代码归档（提交至指定知识库）

• 客户及项目交接（需主管确认）

• 公司设备归还（笔记本电脑、门禁卡、工牌等）

• 财务结算（备用金、报销单等）

• 系统账号注销申请

• 员工手册签收回执归还

9.3 竞业限制

P6及以上员工及核心研发人员在离职后12个月内受竞业限制约束，不得加入主要竞争对手（名单见劳动合同附件）。公司将按月支付竞业限制补偿金（离职前12个月平均工资的30%）。

