-- kb_eval_dataset：22 行
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (1, 1, '新员工入职第一天需要做什么？', '领取工牌和电脑，配置 VPN 和开发环境，与直属 Leader 完成对齐会，阅读代码规范。', '{193}', 1, 'ARCHIVED', NULL, NULL, '2026-06-21 07:34:25.257068', '2026-06-21 07:34:25.257068');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (2, 1, '年假是怎么规定的？', '工作满 1 年未满 10 年享有 5 天年假，工作满 10 年以上享有 10 天年假。', '{193}', 1, 'ARCHIVED', NULL, NULL, '2026-06-21 07:34:25.257068', '2026-06-21 07:34:25.257068');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (3, 2, 'API 限流策略是什么？', '单用户每分钟最多 100 次调用，采用滑动窗口算法，超出后返回 429 状态码。', NULL, 2, 'NEEDS_REVIEW', NULL, NULL, '2026-06-21 07:34:25.257068', '2026-09-07 13:44:52.408777');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (4, 2, '代码提交规范有哪些？', 'Commit message 格式为 type(scope): message，type 包括 feat/fix/docs/refactor。', NULL, 2, 'NEEDS_REVIEW', NULL, NULL, '2026-06-21 07:34:25.257068', '2026-09-07 13:44:30.857464');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (5, 3, '如何申请 API 访问权限？', '在开发者控制台创建 API Key，免费配额为每日 1000 次调用，付费套餐按量计费。', NULL, 3, 'NEEDS_REVIEW', NULL, NULL, '2026-06-21 07:34:25.257068', '2026-09-07 13:44:14.827516');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (39, 1, '新员工入职需要携带哪些材料？', '需携带：身份证原件及复印件（2份）、最高学历证书及学位证书原件及复印件、近6个月内1寸彩色免冠照片2张、上一家公司离职证明原件、银行卡（工资发放专用）、体检报告（入职前30天内）。', '{214}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 20:59:31.128900');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (40, 1, '试用期时长是如何规定的？', '试用期时长按岗位级别确定，一般为1-6个月。', '{214,224}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 20:59:27.738758');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (41, 1, '公司的薪酬结构包括哪些部分？', '公司实行"固定薪资 + 绩效奖金 + 股权激励"的薪酬体系。月固定工资占70%-80%，每月15日发放；季度绩效奖金占15%-25%，依据当季KPI考核结果发放；年终奖视公司业绩，通常为1-6个月固定工资；股权激励视级别，P6及以上岗位可参与期权计划。', '{215}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 13:28:07.423590');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (42, 1, '员工福利包括哪些内容？', '包括：每年一次全面健康体检、每工作日50元餐补、交通补贴（市区内600元/月，郊区1000元/月）、生日礼金500元购物卡、节日福利礼包、员工学习基金每年3000元、健身房报销上限2400元/年等。', '{214,215,216}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 13:28:07.423590');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (43, 1, '公司的标准工作时间是怎样的？', '周一至周五 09:00-18:00，午休时间12:00-13:00（1小时）。法定节假日休息，特殊情况按加班政策执行。', '{217,222}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 20:59:24.328381');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (44, 1, '什么是弹性工作制？', '研发、产品等岗位实行弹性工作制，核心工作时间为10:00-16:00，员工可在此基础上自由调整上下班时间，但每日工作时长不得低于8小时。', '{217}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-10 13:42:10.763552');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (45, 1, '加班如何补偿？', '加班须事先获得主管审批。工作日加班补偿为调休（1:1），节假日加班按法律规定支付三倍工资或调休。超时加班（每月累计超过36小时）须经VP级以上管理者批准。', '{218}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 20:59:17.162016');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (46, 1, '员工年假有多少天？', '年假为5-20天，全薪，需主管审批。具体天数根据工龄确定。', '{215,219}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 20:59:10.462813');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (47, 1, '病假需要提供什么证明？', '病假有证明的按实际天数，薪资按比例发放，需主管+HR审批。', '{215,219}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 23:30:44.170929');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (48, 1, '婚假有多少天？', '婚假3天，全薪，需主管+HR审批。', '{215,219}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-08 12:45:28.852460');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (49, 1, '绩效评级标准是怎样的？', '绩效分为5个等级：S(卓越)10%、A(优秀)25%、B(达标)50%、C(待改进)10%、D(不合格)5%。', '{215,220}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-08 12:46:00.914226');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (50, 1, '员工可以从事兼职工作吗？', '员工不得在任职期间于竞争对手或业务相关公司从事兼职工作，不得以个人名义接受客户或供应商的馈赠（价值超过500元须上报）。副业经营须事先书面告知HR并获得批准。', '{220,221}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-08 12:46:19.560155');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (51, 1, '信息安全方面有哪些要求？', '工作电脑须设置屏幕锁定（离座超过3分钟自动锁屏）；禁止通过个人邮件、微信等渠道传输公司敏感数据；客户数据属于高度机密，仅限有权限的人员访问；离职时须归还全部公司设备及资料，删除个人设备上的公司数据；发现信息安全事件须在1小时内上报信息安全团队。', '{222,223,227}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 15:20:28.711965');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (52, 1, '公司提供哪些培训机会？', '公司提供技能提升课程（每季度至少1次）、管理力发展项目（每年度）、安全合规培训（每年度必修）、行业峰会/外训（视情况，员工申请HR审批）等培训机会。', '{223}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-10 13:42:17.442826');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (53, 1, '公司的晋升体系是怎样的？', '公司设立专业技术（P序列）与管理（M序列）双通道晋升体系。员工可根据自身发展方向选择晋升路径，不强制由技术转管理。晋升评审每年10月启动，晋升须满足在当前级别至少满12个月，且最近两次绩效不低于B。', '{224}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-08 12:45:47.769922');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (54, 1, '员工主动离职需要提前多久通知？', '员工主动离职须提前书面通知，试用期员工提前3天，正式员工提前30天。', '{224}', 1, 'ACTIVE', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-07 13:28:07.423590');
INSERT INTO public.kb_eval_dataset (id, kb_id, question, expected_answer, expected_chunk_ids, created_by, status, review_reason, source_feedback_id, created_at, updated_at) VALUES (55, 1, '公司有哪些申诉渠道？', '公司设立多层级申诉机制：第一层为直属主管（适用于日常工作纠纷）、第二层为人力资源部（适用于薪酬、绩效等制度性纠纷）、第三层为员工关系委员会（适用于重大申诉事项）、匿名举报邮箱ethics@techstars.cn（适用于违规、违纪举报）。', '{226}', 1, 'ARCHIVED', NULL, NULL, '2026-09-07 13:28:07.423590', '2026-09-08 12:45:14.450881');

